pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val) public {
        // Initialize the contract so SetMinSum is callable
        c.Initialized();
        // Try to set MinSum to the fuzzed value via an external call
        bool ok = false;
        try c.SetMinSum(_val) { ok = true; } catch { ok = false; }
        // After the call, MinSum should equal _val on success, or remain unchanged on revert.
        // However, the reference contract never reverts after initialization (it sets MinSum).
        // The buggy contract always reverts, so MinSum remains 0 and ok is false.
        // The property: if the call succeeded, MinSum must equal _val.
        // On the reference this always holds; on the buggy, it fails when ok is false but _val != 0.
        assertTrue(!ok || c.MinSum() == _val);
    }
}

