import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 val) public {
        // Bound to avoid overflow in the subset where val+1 would revert in reference,
