pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val) public {
        // Ensure the contract is initialized before we can call SetMinSum
        c.Initialized();
        // No assume on _val; let the fuzzer try any uint256, including max.
        // SetMinSum may revert if overflow in mutant, but that's fine.
        // We want a rule that holds for reference and fails for mutant for some input.
        // The rule: after any successful call to SetMinSum (regardless of _val), MinSum is at most 2^256-2.
        // The reference always stores exactly _val, so it's ≤ 2^256-1, violating the rule? Wait, rule must hold for reference.
        // Actually 2^256-1 > 2^256-2, so that rule doesn't hold for reference with max uint.
        // We need a rule that holds for ALL inputs for the reference.
        // Reference: MinSum == _val always (after init). Mutant: MinSum == _val+1, which for max uint overflows and reverts.
        // So mutant reverts for max uint, reference succeeds.
        // Rule: SetMinSum should NOT revert for any uint256 input (it succeeds in reference, fails in mutant for max).
        // This is a legitimate universal property.
        bool ok = false;
        try c.SetMinSum(_val) { ok = true; } catch { ok = false; }
        // In reference, ok is always true. In mutant, ok is false for _val = 2^256-1.
        assertTrue(ok);
    }
}

