pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address _log) public {
        // Deploy a helper that acts as a LogFile to obtain its address.
        // The helper address is fuzzed via _log. We use a minimal helper
        // so that c.SetLogFile receives a contract address (any code) and
        // the test does not later depend on the helper's behaviour.
        LogStub stub = new LogStub();
        address stubAddr = address(stub);

        // The bug is the deletion of the assignment inside SetLogFile.
        // On the reference, c.SetLogFile stores _log as the Log address;
        // on the mutant, Log remains uninitialised (address(0)).
        // To expose the difference we call SetLogFile with stubAddr.
        // We must first ensure Initialized() is true, otherwise SetLogFile reverts.
        c.Initialized();
        c.SetLogFile(stubAddr);

        // The public variable Log has an auto-generated getter.
        // Reference: Log() returns stubAddr
        // Mutant:    Log() returns address(0) (the default)
        assertTrue(c.Log() == stubAddr);
    }
}

// Minimal helper that simply exists so that _log can be a contract address.
contract LogStub {
    fallback() external payable {}
}

