pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 lockTime, uint256 amount) public {
        // Bound to admissible domain
        vm.assume(amount > 0 && amount < type(uint128).max);
        lockTime = bound(lockTime, 0, type(uint64).max);

        // Initialize contract
        c.Initialized();
        c.SetMinSum(0);

        // Use a fresh address as the actor
        address actor = address(uint160(uint256(keccak256(abi.encode(lockTime, amount)))));
        vm.assume(actor != address(0));

        // Record starting balance
        uint256 startAccBalance = c.Acc(actor).balance;
        uint256 startActorBalance = actor.balance;

        // Fund actor and call Put
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(lockTime);

        // End balances
        uint256 endAccBalance = c.Acc(actor).balance;
        uint256 endActorBalance = actor.balance;

        // Rule: Acc[actor].balance change equals net Ether sent (amount if called directly)
        // Reference: balance increases by amount; bug: balance decreases by amount
        bool refSatisfied = (endAccBalance == startAccBalance + amount) &&
                            (endActorBalance == startActorBalance - amount);
        // Bug version would have endAccBalance < startAccBalance, so refSatisfied false
        assertTrue(refSatisfied);
    }
}

