contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Restrict amount to avoid overflow in require check; keep wide
        amount = bound(amount, 1, type(uint128).max);
        address actor = address(0x1337);
        vm.deal(actor, amount);
        // Initialize contract to enable operations
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();

        // Record balance before Put
        ( , uint256 balBefore) = c.Acc(actor);

        // Perform Put as actor
        vm.prank(actor);
        c.Put{value: amount}(0);

        // After Put, the contract's Ether balance must be at least the caller's recorded balance
        // In correct version, Acc.balance increases by amount, so contract balance (amount) >= Acc.balance (amount) holds.
        // In buggy version, Acc.balance decreases (becomes balBefore - amount). With balBefore=0 and amount>0, this underflows
        // to a huge number, making the invariant likely false (contract balance small, Acc.balance huge).
        ( , uint256 balAfter) = c.Acc(actor);
        assertTrue(address(c).balance >= balAfter);
    }
}

