import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 lockTime, uint256 fundAmount, uint256 initialUnlock) public {
        // Keep the domain admissible: lockTime must not overflow when added to block.timestamp
        vm.assume(lockTime <= type(uint256).max - block.timestamp);
        // Use reasonable funding amounts
        fundAmount = bound(fundAmount, 1, 100 ether);
        // initialUnlock will be set by a first call with this value
        initialUnlock = bound(initialUnlock, 0, type(uint256).max - block.timestamp);

        // Avoid initialUnlock == 0 distinction irrelevant to property
        // We need an initial unlock time to compare against later
        vm.assume(initialUnlock > 0);

        address user = address(0x1234);
        vm.deal(user, 200 ether);

        // Initialize the contract (required to call SetMinSum etc. but here we just need Put)
        // Put does not need init; just go ahead.

        // First Put to set an initial unlockTime
        vm.prank(user);
        c.Put{value: fundAmount}(initialUnlock);

        uint256 firstUnlock = c.Acc(user).unlockTime;

        // Advance time to ensure block.timestamp changes between calls
        vm.warp(block.timestamp + 1000);

        // Now the second Put with a fresh lockTime parameter
        vm.prank(user);
        c.Put{value: 1}(lockTime);

        uint256 secondUnlock = c.Acc(user).unlockTime;

        // After a Put, the unlock time should be max(previous unlockTime, block.timestamp + lockTime)
        // In the REFERENCE, secondUnlock >= block.timestamp + lockTime (provided that sum > firstUnlock)
        // and also secondUnlock >= firstUnlock (it never decreases).
        // The mutant sets unlockTime = block.timestamp, so it can be lower than firstUnlock or lower than block.timestamp+lockTime.
        // Universal property: unlockTime >= firstUnlock AND unlockTime >= block.timestamp (trivial) AND if block.timestamp+lockTime > firstUnlock then >= block.timestamp+lockTime.
        // Capture all: unlockTime >= block.timestamp + lockTime || unlockTime == firstUnlock (when block.timestamp+lockTime <= firstUnlock).
        // But the mutant may break this by setting to block.timestamp, which may be < firstUnlock or < block.timestamp+lockTime.

        bool ok = (secondUnlock >= block.timestamp + lockTime) || (secondUnlock == firstUnlock);
        assertTrue(ok);
    }
}

