        vm.assume(lockTime <= 365 days);

        // Initialize contract
        c.Initialized();
        c.SetMinSum(0); // Allow small amounts

        // Setup a user
        address user = makeAddr("user");
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.Put{value: depositAmount}(lockTime);

        uint depositTimestamp = block.timestamp;
        uint unlockAt = depositTimestamp + lockTime;

        // Warp to collectTimestamp: exactly unlockAt - collectDelay (so reference should fail if collectDelay > 0)
        vm.assume(collectDelay <= unlockAt);
        uint collectTimestamp = unlockAt - collectDelay;
        vm.warp(collectTimestamp);

        // Try to collect
        bool success;
        vm.prank(user);
        try c.Collect(collectAmount) {
            success = true;
        } catch {
            success = false;
        }

        // General rule: If block.timestamp <= unlockTime, Collect should revert
        // Here collectTimestamp = unlockAt - collectDelay, so block.timestamp <= unlockTime iff collectDelay > 0
        // Bug removes this check, so it won't revert when it should.
        if (collectDelay > 0) {
            // Reference must revert (success == false), mutant may succeed
            assertTrue(!success);
        } else {
            // At unlockTime or after, both should succeed (ignore for test, just a pass)
            assertTrue(true);
        }
    }
}

