contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 _lockTime, uint256 _putAmount, uint256 _collectAmount, uint256 _warpTime) public {
        // Keep lockTime within reasonable bounds to avoid overflow issues
        vm.assume(_lockTime > 0 && _lockTime <= 365 days);
        vm.assume(_putAmount > 0 && _putAmount <= 100 ether);
        vm.assume(_collectAmount > 0 && _collectAmount <= 100 ether);
        // Ensure warpTime is positive but not more than _lockTime, so we are still locked
        vm.assume(_warpTime > 0 && _warpTime <= _lockTime);

        // Setup: Initialize the contract and set MinSum to 0 so balance conditions are easily satisfied
        c.SetMinSum(0);
        c.Initialized();

        // User makes a Put with a lockTime
        address user = address(0x1);
        vm.deal(user, _putAmount);
        vm.prank(user);
        c.Put{value: _putAmount}(_lockTime);

        // Advance time so that it is still before the unlockTime
        vm.warp(_warpTime);

        // Ensure that at this point, balance conditions are met but time condition is not
        // (balance >= MinSum is true because MinSum=0, balance >= _collectAmount is enforced by assumption below)
        vm.assume(_putAmount >= c.MinSum() && _putAmount >= _collectAmount);

        // Attempt Collect and check if it reverts
        vm.prank(user);
        bool ok;
        try c.Collect(_collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: when block.timestamp <= acc.unlockTime (i.e., lock has not expired),
        // and balance conditions are met, Collect MUST revert.
        // The reference contract always reverts in this situation; the buggy mutant does not.
        assertTrue(!ok);
    }
}
